public class ConversationMemoryManager
{
    private readonly ILogger _logger;
    private readonly IChatClient _summarizer; // Low-cost model for summarization
    private const int MaxRecentMessages = 10;
    private const int MaxTokens = 10000; // for the summarization model

    public async Task<List<ChatMessage>> PruneAsync(
        List<ChatMessage> messages, ITokenizer tokenizer)
    {
        var tokenCount = tokenizer.CountTokens(messages);
        if (tokenCount <= MaxTokens)
            return messages;

        // Keep system prompt + last N messages
        var systemMessages = messages.Where(m => m.Role == ChatRole.System).ToList();
        var recentMessages = messages
            .Where(m => m.Role != ChatRole.System)
            .TakeLast(MaxRecentMessages)
            .ToList();

        // Summarize the rest
        var olderMessages = messages
            .Skip(systemMessages.Count)
            .Take(messages.Count - systemMessages.Count - MaxRecentMessages)
            .ToList();

        if (olderMessages.Any())
        {
            var summary = await SummarizeAsync(olderMessages);
            var summaryMessage = new ChatMessage(ChatRole.User,
                $"Previous conversation summary: {summary}");
            systemMessages.Add(summaryMessage);
        }

        return systemMessages.Concat(recentMessages).ToList();
    }

    private async Task<string> SummarizeAsync(List<ChatMessage> messages)
    {
        var summaryRequest = $"Summarize the key points of this conversation in 3 sentences:"
            + string.Join("\n", messages.Select(m => $"[{m.Role}]: {m.Text}"));

        var response = await _summarizer.CompleteAsync(summaryRequest);
        return response.Message.Text;
    }
}

public class UserLongTermMemory
{
    private readonly IVectorStore _vectorStore;
    private readonly IRedisCache _keyValue;
    private readonly ILogger _logger;

    // Retrieve top-K semantically relevant facts for a user
    public async Task<List<string>> RecallFactsAsync(
        string userId, string query, int topK = 5, CancellationToken ct = default)
    {
        // Use user-specific namespace to partition memory
        var collection = _vectorStore.GetCollection<Guid, MemoryRecord>("user-facts");
        var queryEmbedding = await _embeddingService.GenerateAsync(query, ct);

        var results = await collection.VectorizedSearchAsync(
            queryEmbedding, new() { TopK = topK }, ct);

        return results.Select(r => r.Record.Payload).ToList();
    }

    // Store a new fact with metadata
    public async Task StoreFactAsync(string userId, string fact, Dictionary<string, object> metadata, CancellationToken ct = default)
    {
        var embedding = await _embeddingService.GenerateAsync(fact, ct);
        var record = new MemoryRecord
        {
            Id = Guid.NewGuid().ToString(),
            Vector = embedding,
            Payload = fact,
            Metadata = new Dictionary<string, object>
            {
                ["userId"] = userId,
                ["createdAt"] = DateTime.UtcNow,
                ["source"] = metadata.GetValueOrDefault("source", "conversation"),
                [...metadata]
            }
        };

        await collection.UpsertAsync(record, ct);

        // Update key-value metadata for fast lookups
        await _keyValue.HashSetAsync($"user:{userId}:facts", fact, DateTime.UtcNow, ct);
    }
}
